package com.etendoerp.copilot.toolpack.tools;
import java.nio.file.Files;import java.nio.file.Path;import java.nio.file.StandardCopyOption;import javax.enterprise.context.ApplicationScoped;import javax.inject.Named;import org.codehaus.jettison.json.JSONObject;import com.etendoerp.copilot.engine.tool.ServerTool;import com.etendoerp.copilot.engine.tool.ToolExecutionContext;import dev.langchain4j.agent.tool.ToolSpecification;
@ApplicationScoped @Named("FileCopyTool") public class FileCopyTool implements ServerTool {
 public String name(){return "FileCopyTool";}
 public ToolSpecification specification(){return FileToolSupport.spec(name(),"This tool receives two paths, one of a file and another of a directory, copies the file to the directory. Returns the path of the copied file.","{\"source_path\":{\"type\":\"string\",\"title\":\"Source Path\",\"description\":\"The path of the file to read.\"},\"destination_directory\":{\"type\":\"string\",\"title\":\"Destination Directory\",\"description\":\"The path of the directory to copy the file.\"}}","source_path","destination_directory");}
 public String execute(JSONObject a,ToolExecutionContext c)throws Exception{Path src=FileToolSupport.readPath(c,FileToolSupport.requiredString(a,"source_path"));Path dir=ToolWorkspace.resolveWrite(c,FileToolSupport.requiredString(a,"destination_directory"));Files.createDirectories(dir);ToolWorkspace.resolveWrite(c,dir.toString());Path dest=FileToolSupport.writePath(c,dir.resolve(src.getFileName()).toString());FileToolSupport.writeBytes(c,dest.toString(),Files.readAllBytes(src));return new JSONObject().put("file_path",dest.toString()).toString();}
}
